'use client';

import {
  useEffect,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from 'react';
import { useReducedMotion } from './use-reduced-motion';
import './scroll-snap-story-rail.css';

export interface ScrollSnapStoryRailProps {
  slides: ReactNode[];
  label: string;
  className?: string;
}

/**
 * A horizontal story using the browser's own scroll snapping, so swipes,
 * trackpads and Shift+wheel all land on a slide. Previous and Next scroll
 * to the same snap points, and a bar shows how far through you are.
 */
export function ScrollSnapStoryRail({
  slides,
  label,
  className = '',
}: ScrollSnapStoryRailProps) {
  const track = useRef<HTMLDivElement>(null);
  const [index, setIndex] = useState(0);
  const reduced = useReducedMotion();

  useEffect(() => {
    const el = track.current;
    if (!el) return;
    let frame = 0;
    const update = () => {
      frame = 0;
      const items = Array.from(el.children) as HTMLElement[];
      let best = 0;
      items.forEach((item, i) => {
        if (
          Math.abs(item.offsetLeft - el.scrollLeft) <
          Math.abs(items[best].offsetLeft - el.scrollLeft)
        )
          best = i;
      });
      if (el.scrollLeft + el.clientWidth >= el.scrollWidth - 2)
        best = items.length - 1;
      setIndex(best);
    };
    const onScroll = () => {
      if (!frame) frame = requestAnimationFrame(update);
    };
    el.addEventListener('scroll', onScroll, { passive: true });
    return () => {
      el.removeEventListener('scroll', onScroll);
      cancelAnimationFrame(frame);
    };
  }, [slides.length]);

  const go = (next: number) => {
    const el = track.current;
    const target = el?.children[next] as HTMLElement | undefined;
    if (el && target)
      el.scrollTo({
        left: target.offsetLeft,
        behavior: reduced ? 'auto' : 'smooth',
      });
  };

  return (
    <div
      className={`mg-snap ${className}`}
      role='region'
      aria-roledescription='carousel'
      aria-label={label}
      style={{ '--mg-progress': (index + 1) / slides.length } as CSSProperties}
    >
      <div
        ref={track}
        className='mg-snap__track'
        tabIndex={0}
        aria-label={`${label} slides`}
      >
        {slides.map((slide, i) => (
          <div
            key={i}
            className='mg-snap__slide'
            role='group'
            aria-roledescription='slide'
            aria-label={`${i + 1} of ${slides.length}`}
          >
            {slide}
          </div>
        ))}
      </div>
      <div className='mg-snap__bar' aria-hidden='true'>
        <span />
      </div>
      <div className='mg-snap__controls'>
        <button
          type='button'
          onClick={() => go(index - 1)}
          disabled={index === 0}
        >
          ← Previous
        </button>
        <span role='status'>
          {index + 1} of {slides.length}
        </span>
        <button
          type='button'
          onClick={() => go(index + 1)}
          disabled={index === slides.length - 1}
        >
          Next →
        </button>
      </div>
    </div>
  );
}

.mg-snap {
  display: grid;
  gap: 10px;
  color: var(--mg-text, #ffffff);
}

.mg-snap__track {
  /* Children measure their offsets from here. */
  position: relative;
  display: flex;
  gap: 12px;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
}

.mg-snap__track::-webkit-scrollbar {
  display: none;
}

.mg-snap__track:focus-visible {
  outline: 3px solid var(--mg-accent-text, #dce9f7);
  outline-offset: 2px;
  border-radius: 14px;
}

.mg-snap__slide {
  flex: 0 0 86%;
  min-height: 150px;
  padding: 18px;
  border-radius: 14px;
  background: var(--mg-raised, #262626);
  color: #ffffff;
  scroll-snap-align: start;
}

.mg-snap__slide:nth-child(even) {
  background: var(--mg-accent, #eaf2fb);
  color: #080808;
}

.mg-snap__bar {
  height: 4px;
  overflow: hidden;
  border-radius: 2px;
  background: #262626;
}

.mg-snap__bar span {
  display: block;
  height: 100%;
  background: var(--mg-accent, #eaf2fb);
  transform: scaleX(var(--mg-progress));
  transform-origin: left;
  transition: transform 300ms ease;
}

.mg-snap__controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.mg-snap__controls span {
  color: #b8b8b8;
  font-size: 13px;
}

.mg-snap__controls button {
  min-height: 44px;
  padding: 0 12px;
  border: 1px solid var(--mg-line-strong, #474747);
  border-radius: 8px;
  background: #121212;
  color: inherit;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.mg-snap__controls button:disabled {
  opacity: 0.45;
  cursor: default;
}

.mg-snap__controls button:focus-visible {
  outline: 2px solid var(--mg-accent-text, #dce9f7);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  .mg-snap__bar span {
    transition: none;
  }
}

'use client';

import { useEffect, useState } from 'react';

/** True when the user has asked for reduced motion. Follows live changes. */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const query = window.matchMedia('(prefers-reduced-motion: reduce)');
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener('change', update);
    return () => query.removeEventListener('change', update);
  }, []);
  return reduced;
}
